132: function parseLoose(str) {
133:   const value = parseFloat(String(str).replace(/[^0-9.]/g, '')) || 0;
134:   if (/B/i.test(str)) return value * 1_000_000_000;
135:   if (/M/i.test(str)) return value * 1_000_000;
136:   if (/K/i.test(str)) return value * 1_000;
137:   return value;
138: }
