391:   if (view === 'assets') body.innerHTML = assetsPanel(f, s);
392:   if (view === 'travel') body.innerHTML = travelPanel(f, s);
393:   if (view === 'ledger') body.innerHTML = ledgerPanel(f, s);
394:   hydrateIcons(body);
